<template><div class="metrics"><el-card v-for="item in rows" :key="item.operation_type"><div class="label">{{ item.operation_type }}</div><strong>{{ item.operation_count || 0 }}</strong><small>{{ item.latest_time || '暂无操作' }}</small></el-card></div></template><script>export default{name:'OperationsMetrics',props:{rows:{type:Array,default:()=>[]}}}</script><style scoped>.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:16px 0}.label,small{display:block;color:#64748b}strong{display:block;font-size:28px;margin:8px 0}</style>
